import Foundation

// MARK: - Walking Through Grief Content Expansion (Entries 9–20)

extension ContentLibrary {

    static let griefContentExpansion: [DayContent] = [
        DayContent(
            scriptureReference: "Psalm 34:18",
            scriptureText: "The Lord is close to the brokenhearted and saves those who are crushed in spirit.",
            devotionalTitle: "Close to the Broken",
            devotionalText: "Grief can make God feel distant, but the truth is the opposite. He draws closer when you're broken. He doesn't stand at a distance waiting for you to pull yourself together. He moves toward your pain. If you feel crushed in spirit today, know that God is not far — He's closer than He's ever been.",
            prayerText: "Lord, I feel broken today. But I trust Your Word that says You are close to me right now. Don't let me believe the lie that You've abandoned me in my grief. Save me from this crushed spirit. Hold me together when I feel like falling apart. Your nearness is my comfort. In Jesus' name, amen.",
            reflectionPrompt: "Can you sense God's closeness in your grief, or does He feel far away?",
            actionSteps: ["Sit quietly and invite God into your grief — tell Him exactly how you feel", "Read Psalm 34:18 three times, slowly, letting each word land"]
        ),
        DayContent(
            scriptureReference: "Revelation 21:4",
            scriptureText: "He will wipe every tear from their eyes. There will be no more death or mourning or crying or pain, for the old order of things has passed away.",
            devotionalTitle: "Tears Have an Expiration Date",
            devotionalText: "Grief feels endless, but it isn't. God promises a day when every tear will be wiped away — personally, tenderly, by His own hand. Death, mourning, crying, and pain are not forever. They belong to the old order. A new order is coming. You grieve with hope because the story doesn't end at the grave. The best chapter hasn't been written yet.",
            prayerText: "Lord, I hold onto this promise today. A day is coming when there will be no more tears, no more death, no more pain. Sustain me with this hope. Let the promise of eternity bring comfort to my present grief. I grieve, but not without hope. The best is yet to come. In Jesus' name, amen.",
            reflectionPrompt: "How does the promise of no more tears change the way you carry today's grief?",
            actionSteps: ["Write down the name of someone you've lost and a hope you hold for eternity", "Share Revelation 21:4 with someone else who is grieving"]
        ),
        DayContent(
            scriptureReference: "John 11:35",
            scriptureText: "Jesus wept.",
            devotionalTitle: "Permission to Weep",
            devotionalText: "The shortest verse in the Bible carries one of the most powerful truths: Jesus cried. He stood at the grave of His friend Lazarus and wept — even though He was about to raise him from the dead. Jesus doesn't condemn your tears. He joins them. If the Son of God wept, you have full permission to grieve. Tears are not weakness; they're a reflection of love.",
            prayerText: "Jesus, You wept. You understand my tears because You've shed Your own. Thank You for not judging my grief. Give me permission to cry when I need to, and comfort me when the tears come. You loved deeply enough to weep, and so do I. Meet me in my tears today. In Jesus' name, amen.",
            reflectionPrompt: "Have you given yourself permission to fully grieve, or are you holding back tears?",
            actionSteps: ["Allow yourself to cry today without trying to stop it — let grief have its moment", "Journal about what your tears are saying — what loss are they honoring?"]
        ),
        DayContent(
            scriptureReference: "Psalm 147:3",
            scriptureText: "He heals the brokenhearted and binds up their wounds.",
            devotionalTitle: "The God Who Binds Wounds",
            devotionalText: "Healing from grief isn't instant — it's a process of binding wounds. God doesn't just acknowledge your broken heart; He actively heals it. Like a skilled physician wrapping a wound, He tenderly applies His presence, His promises, and His people to your pain. The wound may leave a scar, but scars are evidence of healing, not just injury.",
            prayerText: "Lord, my heart is broken. Begin Your healing work in me. Bind up my wounds with Your love and tenderness. I know healing takes time, and I give You that time. Don't let bitterness infect the wound. Let Your healing produce a scar that tells a story of Your faithfulness. In Jesus' name, amen.",
            reflectionPrompt: "Where is God already beginning to heal your broken heart, even if the wound is still fresh?",
            actionSteps: ["Identify one small sign of healing in your grief journey and thank God for it", "Talk to someone who has walked through grief and come out the other side"]
        ),
        DayContent(
            scriptureReference: "2 Corinthians 1:3-4",
            scriptureText: "Praise be to the God and Father of our Lord Jesus Christ, the Father of compassion and the God of all comfort, who comforts us in all our troubles, so that we can comfort those in any trouble with the comfort we ourselves receive from God.",
            devotionalTitle: "Comforted to Comfort",
            devotionalText: "God's comfort has a purpose beyond your own relief. He comforts you so that someday — when you're ready — you can comfort others walking the same dark road. Your grief, when surrendered to God, becomes a ministry. Not today, perhaps. But eventually, the comfort you receive will overflow into someone else's pain. Your suffering won't be wasted.",
            prayerText: "Father of compassion, God of all comfort, comfort me in my trouble today. And when the time is right, use my grief to help someone else. Don't let my suffering be wasted. Redeem my pain for Your purposes. I trust that one day this grief will become a source of comfort for another broken heart. In Jesus' name, amen.",
            reflectionPrompt: "Can you imagine a day when your grief could comfort someone else walking through loss?",
            actionSteps: ["Accept comfort from someone today without deflecting or minimizing your pain", "When you're ready, reach out to someone going through a similar loss"]
        ),
        DayContent(
            scriptureReference: "Romans 8:28",
            scriptureText: "And we know that in all things God works for the good of those who love him, who have been called according to his purpose.",
            devotionalTitle: "Good From Grief",
            devotionalText: "This verse doesn't say all things are good — loss is not good. It says God works in all things for good. There's a massive difference. God doesn't cause your grief, but He refuses to waste it. He is at work right now, weaving your pain into a larger story of redemption. You may not see it yet. That's okay. Trust the Weaver, even when you can't see the tapestry.",
            prayerText: "Lord, I can't see any good right now. But I choose to trust that You are working in all things. I don't call this loss good, but I believe You can bring good from it. Help me trust the Weaver when I can't see the tapestry. I hold onto this promise with whatever faith I have today. In Jesus' name, amen.",
            reflectionPrompt: "Is it hard for you to believe God can bring good from this loss? Be honest with Him about that.",
            actionSteps: ["Write an honest prayer to God about how you feel about Romans 8:28 right now", "Ask someone you trust to share a story of how God brought good from a painful season"]
        ),
        DayContent(
            scriptureReference: "Psalm 30:5",
            scriptureText: "For his anger lasts only a moment, but his favor lasts a lifetime; weeping may stay for the night, but rejoicing comes in the morning.",
            devotionalTitle: "Morning Is Coming",
            devotionalText: "Night is the hardest part of grief — the quiet hours when loss feels heaviest. But the psalmist promises that weeping has a time limit. It may stay for the night, but it doesn't live there permanently. Morning is coming. Joy will return. Not because you forget the one you lost, but because God's favor carries you into a new season. Hold on through the night.",
            prayerText: "Lord, it feels like night right now. The tears come and the weight is heavy. But I hold onto Your promise that morning is coming. Joy will return. Help me endure this night season, knowing that Your favor lasts a lifetime. I trust that weeping won't last forever. Morning is on its way. In Jesus' name, amen.",
            reflectionPrompt: "Do you believe morning is coming? What small signs of dawn can you see?",
            actionSteps: ["Watch the sunrise tomorrow and let it be a physical reminder that morning always comes", "Write down one thing — however small — that brought you a moment of joy recently"]
        ),
        DayContent(
            scriptureReference: "Isaiah 53:3-4",
            scriptureText: "He was despised and rejected by mankind, a man of suffering, and familiar with pain. He took up our pain and bore our suffering.",
            devotionalTitle: "He Knows Your Pain",
            devotionalText: "Jesus is not unfamiliar with your grief. He is described as a man of suffering — someone acquainted with pain at the deepest level. He was rejected, despised, and ultimately killed. When you bring your grief to Jesus, you're not bringing it to someone who doesn't understand. He bore your suffering. He carried your pain. He gets it.",
            prayerText: "Jesus, You are a man of suffering, familiar with pain. You don't stand at a distance from my grief — You entered it. You bore my suffering on the cross. Thank You for understanding. Thank You for not dismissing my pain. Walk with me through this season as the One who truly knows what loss feels like. In Jesus' name, amen.",
            reflectionPrompt: "Does it comfort you to know that Jesus personally understands suffering and grief?",
            actionSteps: ["Read Isaiah 53 slowly and notice how Jesus experienced grief", "Talk to Jesus about your grief as you would talk to someone who has been through the same thing"]
        ),
        DayContent(
            scriptureReference: "Lamentations 3:22-23",
            scriptureText: "Because of the Lord's great love we are not consumed, because his compassions never fail. They are new every morning; great is your faithfulness.",
            devotionalTitle: "New Mercies Every Morning",
            devotionalText: "Jeremiah wrote Lamentations from the rubble of Jerusalem — total devastation. Yet even in utter loss, he could see one thing clearly: God's compassions are new every morning. Grief doesn't get yesterday's leftover mercy. You get fresh compassion today. Even if yesterday was unbearable, today brings new mercies. Great is His faithfulness — especially in your darkest seasons.",
            prayerText: "Lord, Your compassions never fail. Even in this devastation, Your mercies are new this morning. I am not consumed because of Your great love. Thank You for fresh mercy today — I need every drop of it. Great is Your faithfulness, even when my faith feels small. In Jesus' name, amen.",
            reflectionPrompt: "What new mercy from God do you need this morning?",
            actionSteps: ["Each morning this week, before getting out of bed, whisper 'New mercies today'", "Write Lamentations 3:22-23 on your bathroom mirror as a daily reminder"]
        ),
        DayContent(
            scriptureReference: "1 Thessalonians 4:13",
            scriptureText: "Brothers and sisters, we do not want you to be uninformed about those who sleep in death, so that you do not grieve like the rest of mankind, who have no hope.",
            devotionalTitle: "Grief With Hope",
            devotionalText: "Paul doesn't say 'don't grieve.' He says don't grieve without hope. Christians grieve — deeply, honestly, painfully. But we grieve differently because we know this isn't the end. Death doesn't have the final word. Reunion is coming. Hope doesn't eliminate grief, but it transforms it. You carry sorrow in one hand and hope in the other.",
            prayerText: "Lord, I grieve today — and that's okay. But I refuse to grieve without hope. I hold onto the promise that death is not the end, that separation is temporary, and that You hold both me and my loved one in Your hands. Give me strength to carry both sorrow and hope. In Jesus' name, amen.",
            reflectionPrompt: "What hope do you hold onto that makes your grief different from grief without God?",
            actionSteps: ["Write a letter to the person you've lost, telling them about the hope you hold", "Share the hope you have with someone who is grieving without faith"]
        ),
        DayContent(
            scriptureReference: "Psalm 73:26",
            scriptureText: "My flesh and my heart may fail, but God is the strength of my heart and my portion forever.",
            devotionalTitle: "When Your Heart Fails",
            devotionalText: "Grief can make your heart feel like it's failing — emotionally, physically, spiritually. The psalmist knew this feeling. But he discovered that even when his own heart couldn't keep going, God became its strength. God doesn't just give you strength; He becomes your strength. When you have nothing left, He is your portion. Forever.",
            prayerText: "Lord, my heart is failing today. I don't have the strength to carry this grief. But You are the strength of my heart. When I can't go on, You go on for me. You are my portion — all I need, all I have, all I want. Sustain me with Your strength because mine is gone. In Jesus' name, amen.",
            reflectionPrompt: "In what way do you need God to be the strength of your heart today?",
            actionSteps: ["When you feel your heart failing today, pause and say 'God, be my strength right now'", "Rest today — physically and emotionally — and let God carry what you cannot"]
        ),
        DayContent(
            scriptureReference: "Ecclesiastes 3:1,4",
            scriptureText: "There is a time for everything, and a season for every activity under the heavens... a time to weep and a time to laugh, a time to mourn and a time to dance.",
            devotionalTitle: "A Season for Mourning",
            devotionalText: "Grief is a season — not a failure, not a sign of weak faith, but a legitimate season of life. Solomon validated mourning as part of the human experience. You don't need to rush through it or apologize for it. There is a time to weep, and when that time comes, let it come. But also hold onto this: the season of dancing will come too. Give yourself permission to be where you are.",
            prayerText: "Lord, I'm in a season of mourning. Help me not to rush through it or be ashamed of it. This is a legitimate season, and You are with me in it. But I also hold onto the promise that a time to dance is coming. Until then, sit with me in this season of weeping. I trust Your timing for all things. In Jesus' name, amen.",
            reflectionPrompt: "Are you giving yourself permission to be in this season, or are you trying to skip ahead?",
            actionSteps: ["Give yourself permission today to feel whatever you're feeling without judgment", "Mark your calendar one month from now and write 'Check in — how has the season shifted?'"]
        ),
    ]
}
